                    "weighProps",
                    "plotWidth",
                    "plotHeight",
                    "plotPointSize",
                    "plotLineWidth",
                    "plotNcol",
                    "plotLegend",
                    "plotAxisAngle",
                    "plotYRange",
                    "plotValueLabels",
                    "plotPalette")))
            self$add(jmvcore::Html$new(
                options=options,
                name="interpretation",
                title="Applied interpretation"))
            self$add(jmvcore::Html$new(
                options=options,
                name="reproducibility",
                title="Reproducibility",
                visible="(showRepro)"))
            self$add(jmvcore::Html$new(
                options=options,
                name="notes",
                title="Notes"))}))

mlmsaBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "mlmsaBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "MokkenLab",
                name = "mlmsa",
                version = c(0,1,0),
                options = options,
                results = mlmsaResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Two-Level Mokken Scale Analysis
#'
#' Within-subject, between-subject and ratio scalability coefficients for 
#' raters nested in subjects (for example, students rating their teacher), 
#' with standard errors, confidence intervals, tests, intraclass correlations, 
#' weights for Guttman errors and plain-language interpretation.
#' 
#' @param data .
#' @param subject .
#' @param vars .
#' @param reportLang .
#' @param showKeySummary .
#' @param showChoicesGuide .
#' @param showGuides .
#' @param showRepro .
#' @param naHandling .
#' @param twowaySets .
#' @param twowaySeed .
#' @param scoreRange .
#' @param scoreMin .
#' @param scoreMax .
#' @param negItems .
#' @param se .
#' @param ci .
#' @param ciWidth .
#' @param typeCI .
#' @param weighProps .
#' @param showHij .
#' @param showCov .
#' @param showZ .
#' @param zLowerbound .
#' @param typeZ .
#' @param showICC .
#' @param showWeights .
#' @param levelPlot .
#' @param plotWidth .
#' @param plotHeight .
#' @param plotPointSize .
#' @param plotLineWidth .
#' @param plotNcol .
#' @param plotLegend .
#' @param plotAxisAngle .
#' @param plotYRange .
#' @param plotValueLabels .
#' @param plotPalette .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$cacheStore} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$intro} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$keySummary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$choicesGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$mlGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$scale} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$items} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pairs} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$covH} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$covHi} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$covHij} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$icc} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$weights} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$levelPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$interpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reproducibility} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
mlmsa <- function(
    data,
    subject = NULL,
    vars,
    reportLang = "en",
    showKeySummary = TRUE,
    showChoicesGuide = FALSE,
    showGuides = TRUE,
    showRepro = TRUE,
    naHandling = "listwise",
    twowaySets = 1,
    twowaySeed = 2026,
    scoreRange = "observed",
    scoreMin = 0,
    scoreMax = 4,
    negItems = list(),
    se = TRUE,
    ci = TRUE,
    ciWidth = 95,
    typeCI = "WB",
    weighProps = TRUE,
    showHij = FALSE,
    showCov = FALSE,
    showZ = TRUE,
    zLowerbound = 0,
    typeZ = "WB",
    showICC = TRUE,
    showWeights = FALSE,
    levelPlot = TRUE,
    plotWidth = 0,
    plotHeight = 0,
    plotPointSize = 2,
    plotLineWidth = 0.8,
    plotNcol = 0,
    plotLegend = "bottom",
    plotAxisAngle = "a45",
    plotYRange = "full",
    plotValueLabels = FALSE,
    plotPalette = "jamovi") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("mlmsa requires jmvcore to be installed (restart may be required)")

    if ( ! missing(subject)) subject <- jmvcore::resolveQuo(jmvcore::enquo(subject))
    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(negItems)) negItems <- jmvcore::resolveQuo(jmvcore::enquo(negItems))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(subject), subject, NULL),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(negItems), negItems, NULL))


    options <- mlmsaOptions$new(
        subject = subject,
        vars = vars,
        reportLang = reportLang,
        showKeySummary = showKeySummary,
        showChoicesGuide = showChoicesGuide,
        showGuides = showGuides,
        showRepro = showRepro,
        naHandling = naHandling,
        twowaySets = twowaySets,
        twowaySeed = twowaySeed,
        scoreRange = scoreRange,
        scoreMin = scoreMin,
        scoreMax = scoreMax,
        negItems = negItems,
        se = se,
        ci = ci,
        ciWidth = ciWidth,
        typeCI = typeCI,
        weighProps = weighProps,
        showHij = showHij,
        showCov = showCov,
        showZ = showZ,
        zLowerbound = zLowerbound,
        typeZ = typeZ,
        showICC = showICC,
        showWeights = showWeights,
        levelPlot = levelPlot,
        plotWidth = plotWidth,
        plotHeight = plotHeight,
        plotPointSize = plotPointSize,
        plotLineWidth = plotLineWidth,
        plotNcol = plotNcol,
        plotLegend = plotLegend,
        plotAxisAngle = plotAxisAngle,
        plotYRange = plotYRange,
        plotValueLabels = plotValueLabels,
        plotPalette = plotPalette)

    analysis <- mlmsaClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

